  values
    ('legenda-o-aleksym', 'streszczenie', 'streszczenie Legenda o św. Aleksym Autor nieznany aleks pod schod',
      'Aleksy porzuca dostatek i dom, by przyjąć życie ubogiego pielgrzyma. Wraca niepoznany i przez lata przebywa pod schodami rodzinnego domu. Jego tożsamość wychodzi na jaw po śmierci.'),
    ('legenda-o-aleksym', 'wydarzenia', 'plan wydarzeń przebieg kolejność Legenda o św. Aleksym Autor nieznany aleks pod schod',
      '1. [Po ślubie] Aleksy odchodzi z domu.
2. [Obce miasto] Rozdaje majątek i żyje z jałmużny.
3. [Powrót] Zamieszkuje pod schodami jako nierozpoznany ubogi.
4. [Finał] Pismo pozostawione przez Aleksego pozwala ustalić jego tożsamość.'),
    ('legenda-o-aleksym', 'geneza', 'geneza Legenda o św. Aleksym Autor nieznany średniowiecze aleks pod schod',
