    ('wyznania-augustyna', 'streszczenie', 'streszczenie Wyznania Augustyn z Hippony gruszk augustyn',
      'Augustyn zwraca się do Boga, ponownie rozpatrując własną biografię. W księdze II kradzież gruszek pozwala mu zastanowić się nad motywem działania, z którego nie wynikała istotna korzyść.'),
    ('wyznania-augustyna', 'wydarzenia', 'plan wydarzeń przebieg kolejność Wyznania Augustyn z Hippony gruszk augustyn',
      '1. [Księga II] Mówiący przywołuje kradzież owoców w towarzystwie innych chłopców.
2. [Księga II] Odróżnia wartość owoców od przyjemności przekroczenia zakazu.
3. [Księga II] Rozważa znaczenie udziału grupy.'),
    ('wyznania-augustyna', 'geneza', 'geneza Wyznania Augustyn z Hippony późna starożytność gruszk augustyn',
      'Tekst łączy retrospekcję biograficzną, modlitwę i namysł filozoficzny. Autor interpretuje młodzieńcze doświadczenia z późniejszej perspektywy religijnej.'),
    ('wyznania-augustyna', 'bohaterowie', 'bohaterowie Wyznania Augustyn z Hippony gruszk augustyn',
      'Augustyn jest narratorem oraz osobą oceniającą przeszłe działania. Towarzysze kradzieży są istotni dla namysłu nad działaniem w grupie.'),
    ('wyznania-augustyna', 'motywy', 'motywy Wyznania Augustyn z Hippony gruszk augustyn',
      'Epizod z gruszkami służy analizie wyboru zła bez wyraźnego materialnego zysku. Wspólne działanie umożliwia też pytanie o wpływ otoczenia.'),
    ('wyznania-augustyna', 'konteksty', 'konteksty Wyznania Augustyn z Hippony gruszk augustyn',
      'Z Księgą Rodzaju można zestawić figurę przekroczenia zakazu związaną z owocem. Istotną różnicą pozostaje forma osobistego rozrachunku.'),
    ('summa-teologiczna', 'streszczenie', 'streszczenie Summa teologiczna Tomasz z Akwinu piec drog tomasz tomasz z akwinu dowod',
      'Tomasz rozpatruje pytania teologiczne w uporządkowanej formie. W kwestii 2 części I argumentuje na rzecz istnienia Boga, wychodząc od obserwowanych cech świata.'),
    ('summa-teologiczna', 'wydarzenia', 'plan wydarzeń przebieg kolejność Summa teologiczna Tomasz z Akwinu piec drog tomasz tomasz z akwinu dowod',
      '1. [Część I, kwestia 2] Autor rozważa, czy istnienie Boga jest samo przez się oczywiste.
2. [Część I, kwestia 2] Rozważa możliwość wykazania istnienia Boga.
3. [Część I, kwestia 2, artykuł 3] Przedstawia pięć dróg argumentacji.'),
    ('summa-teologiczna', 'geneza', 'geneza Summa teologiczna Tomasz z Akwinu średniowiecze piec drog tomasz tomasz z akwinu dowod',
      'Summa jest przykładem średniowiecznej scholastyki. Artykuł porządkuje zarzuty, odpowiedź oraz osobne wyjaśnienia trudności.'),
    ('summa-teologiczna', 'bohaterowie', 'bohaterowie Summa teologiczna Tomasz z Akwinu piec drog tomasz tomasz z akwinu dowod',
      'Nie ma bohaterów fabuły. Autor porządkuje możliwe stanowiska i odpowiada na argumenty przedstawione w rolach rozmówców.'),
    ('summa-teologiczna', 'motywy', 'motywy Summa teologiczna Tomasz z Akwinu piec drog tomasz tomasz z akwinu dowod',
      'Wśród dróg pojawiają się ruch, przyczynowość i przygodność. Przykłady pokazują próbę przejścia od doświadczenia świata do wniosku metafizycznego.'),
    ('summa-teologiczna', 'konteksty', 'konteksty Summa teologiczna Tomasz z Akwinu piec drog tomasz tomasz z akwinu dowod',
      'Z Wyznaniami Augustyna można zestawić dwie formy rozważań religijnych. U Tomasza ważny jest porządek pytania i argumentu, u Augustyna głos osobistego wyznania.'),
    ('gargantua-i-pantagruel', 'streszczenie', 'streszczenie Gargantua i Pantagruel François Rabelais opactw telem picrochol pikroch',
      'Cykl opowiada o olbrzymach, ich wychowaniu, wyprawach i konfliktach. W pierwszej księdze kształcenie Gargantui i wojna z Picrocholem prowadzą do zupełnie odmiennego modelu wspólnoty w opactwie Telemy.'),
    ('gargantua-i-pantagruel', 'wydarzenia', 'plan wydarzeń przebieg kolejność Gargantua i Pantagruel François Rabelais opactw telem picrochol pikroch',
      '1. [Księga I, edukacja] Gargantua zmienia sposób nauki.
2. [Księga I, wojna] Drobny spór przekształca się w konflikt zbrojny.
3. [Księga I, Telema] Nowe opactwo otrzymuje regułę opartą na swobodzie.'),
    ('gargantua-i-pantagruel', 'geneza', 'geneza Gargantua i Pantagruel François Rabelais renesans opactw telem picrochol pikroch',
      'Rabelais korzysta z historii o olbrzymach, parodii i groteski. Utwór przekształca spory o wychowanie, rządzenie i obyczaje w sceny o wyolbrzymionych rozmiarach.'),
    ('gargantua-i-pantagruel', 'bohaterowie', 'bohaterowie Gargantua i Pantagruel François Rabelais opactw telem picrochol pikroch',
      'Gargantua reprezentuje starsze pokolenie olbrzymów, Pantagruel jest jego synem. Picrochol uruchamia konflikt wojenny w pierwszej księdze. Brat Jan jest związany z założeniem Telemy.'),
    ('gargantua-i-pantagruel', 'motywy', 'motywy Gargantua i Pantagruel François Rabelais opactw telem picrochol pikroch',
      'Zmiana edukacji ukazuje różnicę między mechanicznym nauczaniem i ćwiczeniem zdolności. Telema pozwala rozważyć, co ma umożliwić życie bez narzuconych przepisów.'),
    ('gargantua-i-pantagruel', 'konteksty', 'konteksty Gargantua i Pantagruel François Rabelais opactw telem picrochol pikroch',
      'Utwór służy jako kontekst dla renesansowej refleksji o edukacji i dla groteski. Z Ferdydurke można porównać środki przedstawiania form narzucanych uczniom.'),
    ('proby-montaignea', 'streszczenie', 'streszczenie Próby Michel de Montaigne kanibal montaigne',
      'W eseju O kanibalach Montaigne przygląda się europejskim sądom o mieszkańcach Ameryki. Analizuje, jak obyczaj kształtuje znaczenie barbarzyństwa, i zwraca spojrzenie na przemoc we własnym społeczeństwie.'),
    ('proby-montaignea', 'wydarzenia', 'plan wydarzeń przebieg kolejność Próby Michel de Montaigne kanibal montaigne',
      '1. [Księga I, O kanibalach] Autor przywołuje obyczaje opisywane przez podróżników.
2. [Księga I, O kanibalach] Bada sposób wartościowania obcych.
3. [Księga I, O kanibalach] Zestawia ocenę obcych z praktykami europejskimi.'),
    ('proby-montaignea', 'geneza', 'geneza Próby Michel de Montaigne renesans kanibal montaigne',
      'Montaigne kształtuje esej jako próbę myślenia. Łączy lekturę poprzedników, relacje o innych kulturach i obserwację własnych sądów.'),
    ('proby-montaignea', 'bohaterowie', 'bohaterowie Próby Michel de Montaigne kanibal montaigne',
      'Autor przemawia jako rozmówca i komentator, odwołując się do przedstawicieli różnych społeczności. W tekście ważna jest pozycja tego, kto wydaje ocenę.'),
    ('proby-montaignea', 'motywy', 'motywy Próby Michel de Montaigne kanibal montaigne',
      'Pojęcie barbarzyństwa ujawnia zależność sądu od przyzwyczajenia. Zestawienie obyczajów służy również krytyce przemocy dokonywanej przez oceniających.'),
    ('proby-montaignea', 'konteksty', 'konteksty Próby Michel de Montaigne kanibal montaigne',
      'Esej można zestawić z Podróżami z Herodotem wobec pytania o obserwację innej kultury. Montaigne kieruje uwagę na ograniczenia własnego punktu widzenia.'),
    ('lilla-weneda', 'streszczenie', 'streszczenie Lilla Weneda Juliusz Słowacki derwid roza wened wened lechit',
      'Dramat ukazuje walkę Wenedów i Lechitów. Lilla podejmuje próby uratowania ojca, Derwida. Jej działania nie odwracają klęski Wenedów i tragedii ich rodziny.'),
    ('lilla-weneda', 'wydarzenia', 'plan wydarzeń przebieg kolejność Lilla Weneda Juliusz Słowacki derwid roza wened wened lechit',
      '1. [Początek walki] Wenedowie ponoszą straty w starciu z Lechitami.
2. [Niewola] Derwid trafia w ręce przeciwników.
3. [Próby Lilli] Córka stara się ocalić ojca.
4. [Rozstrzygnięcie] Ginie nadzieja na zwycięstwo Wenedów.'),
    ('lilla-weneda', 'geneza', 'geneza Lilla Weneda Juliusz Słowacki romantyzm derwid roza wened wened lechit',
      'Słowacki stworzył fantastyczną opowieść o umownej przeszłości Polski. Los przegranej wspólnoty może być czytany w kontekście rozrachunków po klęsce powstania.'),
    ('lilla-weneda', 'bohaterowie', 'bohaterowie Lilla Weneda Juliusz Słowacki derwid roza wened wened lechit',
      'Derwid jest władcą Wenedów. Lilla i Roza są jego córkami, które inaczej odpowiadają na zagrożenie. Lech i Gwinona stoją po stronie przeciwników.'),
    ('lilla-weneda', 'motywy', 'motywy Lilla Weneda Juliusz Słowacki derwid roza wened wened lechit',
      'Próby Lilli zestawiają osobiste poświęcenie z losem całej zbiorowości. Harfa Derwida wiąże możliwość działania z siłą pieśni i pamięci.'),
    ('lilla-weneda', 'konteksty', 'konteksty Lilla Weneda Juliusz Słowacki derwid roza wened wened lechit',
      'Z Kordianem można porównać pytanie o przyczyny klęski. Umowność pradziejów daje inny sposób mówienia o losie wspólnoty niż odtworzenie konkretnego spisku.'),
    ('nie-boska-komedia', 'streszczenie', 'streszczenie Nie-Boska komedia Zygmunt Krasiński pankrac orc henryk hrabi henryk okop swietej trojcy',
      'Hrabia Henryk porzuca dom pod wpływem wyobrażeń o poezji i patrzy później na rozpad życia rodzinnego. Staje na czele arystokracji walczącej z rewolucją Pankracego. Obie strony konfliktu ponoszą klęskę w różny sposób.'),
    ('nie-boska-komedia', 'wydarzenia', 'plan wydarzeń przebieg kolejność Nie-Boska komedia Zygmunt Krasiński pankrac orc henryk hrabi henryk okop swietej trojcy',
      '1. [Część I] Henryk ulega widmu Dziewicy i odchodzi od rodziny.
2. [Część II] Ujawniają się niezwykłe zdolności i cierpienie Orcia.
3. [Część III] Henryk ogląda obóz rewolucji.
4. [Część IV] Obronę arystokratów kończy klęska.
5. [Część IV] Pankracy doświadcza końcowej wizji i umiera.'),
    ('nie-boska-komedia', 'geneza', 'geneza Nie-Boska komedia Zygmunt Krasiński romantyzm pankrac orc henryk hrabi henryk okop swietej trojcy',
      'Dramat romantyczny łączy historię poety z obrazem gwałtownego konfliktu społecznego. Ukazuje jednocześnie wady arystokracji i przemoc rewolucyjnego obozu.'),
    ('nie-boska-komedia', 'bohaterowie', 'bohaterowie Nie-Boska komedia Zygmunt Krasiński pankrac orc henryk hrabi henryk okop swietej trojcy',
      'Hrabia Henryk jest poetą i dowódcą obrony. Maria i Orcio ponoszą konsekwencje rodzinnej tragedii. Pankracy prowadzi rewolucję.'),
    ('nie-boska-komedia', 'motywy', 'motywy Nie-Boska komedia Zygmunt Krasiński pankrac orc henryk hrabi henryk okop swietej trojcy',
      'Dziewica pozwala mówić o złudzeniu poezji, za którym bohater podąża kosztem bliskich. Rozmowa Henryka z Pankracym wydobywa sprzeczne oczekiwania wobec historii i społeczeństwa.'),
    ('nie-boska-komedia', 'konteksty', 'konteksty Nie-Boska komedia Zygmunt Krasiński pankrac orc henryk hrabi henryk okop swietej trojcy',
      'Dramat można zestawić z utworami o rewolucji, np. Przedwiośniem. Finałowa wizja dodaje konfliktowi perspektywę religijną.'),
    ('noc-listopadowa', 'streszczenie', 'streszczenie Noc listopadowa Stanisław Wyspiański wysock belweder kora demeter listopad',
      'Sceny dramatu rozgrywają się podczas nocy wybuchu powstania listopadowego. Działania spiskowców i postawy władz przeplatają się z obrazami mitologicznymi. Mit nadaje zdarzeniom znaczenie wykraczające poza opis polityczny.'),
    ('noc-listopadowa', 'wydarzenia', 'plan wydarzeń przebieg kolejność Noc listopadowa Stanisław Wyspiański wysock belweder kora demeter listopad',
      '1. [Łazienki] Mitologiczne postacie wchodzą do świata dramatu.
2. [Spisek] Podchorążowie przystępują do działania.
3. [Belweder] Rozgrywa się próba dosięgnięcia władzy wielkiego księcia.
4. [Nocne sceny] Wątki polityczne splatają się z obrazem rozstania Kory i Demeter.'),
    ('noc-listopadowa', 'geneza', 'geneza Noc listopadowa Stanisław Wyspiański Młoda Polska wysock belweder kora demeter listopad',
      'Wyspiański wykorzystał historyczne wydarzenia listopada 1830 r. jako materiał dramatu scenicznego. Umowne spotkanie historii i mitu jest podstawą jego kompozycji.'),
    ('noc-listopadowa', 'bohaterowie', 'bohaterowie Noc listopadowa Stanisław Wyspiański wysock belweder kora demeter listopad',
      'Wśród historycznych postaci są Piotr Wysocki i wielki książę Konstanty. Kora i Demeter pochodzą z mitu i budują dodatkową perspektywę interpretacji nocy.'),
    ('noc-listopadowa', 'motywy', 'motywy Noc listopadowa Stanisław Wyspiański wysock belweder kora demeter listopad',
      'Rozstanie Kory i Demeter łączy zmianę pory życia z pytaniem o powrót i odrodzenie. Podchorążowie pokazują czyn podejmowany w niepewnej sytuacji.'),
    ('noc-listopadowa', 'konteksty', 'konteksty Noc listopadowa Stanisław Wyspiański wysock belweder kora demeter listopad',
      'Z Weselem można porównać obecność postaci pozarealistycznych i pytanie o wspólne działanie. Tło historyczne i konstrukcja konkretnych nocy są różne.'),
    ('borges-opowiadanie', 'streszczenie', 'streszczenie Opowiadanie Borgesa, wybór Jorge Luis Borges tsui pen yu tsun',
      'Bohater uciekający jako szpieg spotyka badacza dzieła swojego przodka. Rozmowa odkrywa, że zagadkowa księga i labirynt mogą tłumaczyć się nawzajem. Opowiadanie wiąże historię szpiegowską z możliwością istnienia wielu przebiegów czasu.'),
    ('borges-opowiadanie', 'wydarzenia', 'plan wydarzeń przebieg kolejność Opowiadanie Borgesa, wybór Jorge Luis Borges tsui pen yu tsun',
      '1. [Relacja szpiega] Uciekający narrator dociera do Stephena Alberta.
2. [Rozmowa] Albert wyjaśnia związek księgi Ts’ui Pena z labiryntem.
3. [Finał] Działanie szpiega pozwala przekazać informację pod pozorem zbrodni.'),
    ('borges-opowiadanie', 'geneza', 'geneza Opowiadanie Borgesa, wybór Jorge Luis Borges literatura XX wieku tsui pen yu tsun',
      'Borges umieszcza zagadnienie filozoficzne wewnątrz fabuły szpiegowskiej. Tekst wykorzystuje formę znalezionej relacji i historię dzieła, które komentują postacie.'),
    ('borges-opowiadanie', 'bohaterowie', 'bohaterowie Opowiadanie Borgesa, wybór Jorge Luis Borges tsui pen yu tsun',
      'Yu Tsun jest autorem przytoczonej relacji. Stephen Albert objaśnia dzieło jego przodka. Ts’ui Pen pozostaje obecny jako twórca księgi i projektu labiryntu.'),
    ('borges-opowiadanie', 'motywy', 'motywy Opowiadanie Borgesa, wybór Jorge Luis Borges tsui pen yu tsun',
      'Labirynt odnosi się do możliwych układów czasu. Rozmowa z Albertem pomaga wyjaśnić, dlaczego sprzeczne zdarzenia mogą współistnieć w przedstawionym modelu.'),
    ('borges-opowiadanie', 'konteksty', 'konteksty Opowiadanie Borgesa, wybór Jorge Luis Borges tsui pen yu tsun',
      'Z Procesem można porównać obraz zagubienia w złożonym układzie, ale w tekście Borgesa labirynt jest przede wszystkim konstrukcją odnoszącą się do czasu i opowieści.')
)
insert into private.wiedza_pestki (przedmiot, utwor, sekcja, tytul, tekst, hasla, zrodlo_url, zrodlo_rodzaj, warunki)
select 'polski', z.utwor, n.sekcja, z.tytul, n.tekst, n.hasla, z.url, z.rodzaj,
  case when z.rodzaj = 'utwór' then 'Autorska notatka Sedno na podstawie wskazanego wydania. Bez przedruku tekstu.'
       else 'Autorska notatka Sedno na podstawie wskazanego materiału edukacyjnego. Bez przedruku materiału.' end
from notatki n join zrodla z using (utwor)
on conflict (przedmiot, utwor, sekcja) do update
set (tytul, tekst, hasla, zrodlo_url, zrodlo_rodzaj, warunki) =
    (excluded.tytul, excluded.tekst, excluded.hasla, excluded.zrodlo_url, excluded.zrodlo_rodzaj, excluded.warunki)
where (wiedza_pestki.tytul, wiedza_pestki.tekst, wiedza_pestki.hasla, wiedza_pestki.zrodlo_url,
       wiedza_pestki.zrodlo_rodzaj, wiedza_pestki.warunki) is distinct from
      (excluded.tytul, excluded.tekst, excluded.hasla, excluded.zrodlo_url, excluded.zrodlo_rodzaj, excluded.warunki);
